// Extraer chat_id, texto del paciente y nombre
const item = $input.first().json;
let chat_id = null;
let text = '';
let user_name = '';

if (item.message) {
  chat_id = String(item.message.chat.id);
  text = item.message.text || '';
  user_name = item.message.from.first_name || 'Paciente';
} else if (item.callback_query) {
  chat_id = String(item.callback_query.message.chat.id);
  text = item.callback_query.data || '';
  user_name = item.callback_query.from.first_name || 'Paciente';
}

return [{
  json: {
    chat_id,
    text,
    user_name,
    sessionId: chat_id
  }
}];

let input = {};
if (typeof query === 'object' && query !== null) {
  input = query;
} else if (typeof query === 'string') {
  try {
    input = JSON.parse(query);
  } catch (e) {
    input = { raw: query };
  }
}
const rawStr = JSON.stringify(input).toLowerCase();

if (rawStr.includes('15:00') || (input.hora && input.hora.includes('15:00'))) {
  return JSON.stringify({
    disponible: false,
    motivo: 'El turno de las 15:00 está reservado para una cirugía prolongada en el consultorio.',
    alternativas_disponibles: ['15:45', '16:30', '17:15', '18:00']
  });
}

return JSON.stringify({
  disponible: true,
  turnos_recomendados: ['10:30', '12:00', '16:30', '17:30'],
  jornada: '08:30 a 20:30 h de lunes a viernes en los 6 consultorios de la clínica'
});

let dni = '';
if (typeof query === 'object' && query !== null) {
  dni = (query.dni || query.DNI || query.documento || '').toString().toUpperCase();
} else if (typeof query === 'string') {
  try {
    const p = JSON.parse(query);
    dni = (p.dni || p.DNI || p.documento || query).toString().toUpperCase();
  } catch (e) {
    dni = query.toUpperCase();
  }
}
const cleanDni = dni.replace(/[^0-9A-Z]/gi, '').trim();

if (!cleanDni) {
  return JSON.stringify({ encontrado: false, mensaje: 'DNI no proporcionado. Solicita DNI al paciente.' });
}

const SUPABASE_URL = 'https://ibnkmbcnkrvwdtrjmcel.supabase.co';
const SERVICE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImlibmttYmNua3J2d2R0cmptY2VsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4OTExNDc4MCwiZXhwIjoyMTA0NjkwNzgwfQ.DwRIy8-ktRewOdswssnA-oC_b4TVLa0jSrLmjkXIS40';

try {
  const resp = await fetch(SUPABASE_URL + '/rest/v1/clinica_pacientes?dni=eq.' + cleanDni + '&select=*', {
    method: 'GET',
    headers: {
      'apikey': SERVICE_KEY,
      'Authorization': 'Bearer ' + SERVICE_KEY,
      'Content-Type': 'application/json'
    }
  });

  const data = await resp.json();
  if (Array.isArray(data) && data.length > 0) {
    const p = data[0];
    const nombreCompleto = ((p.nombre || '') + ' ' + (p.apellidos || '')).trim();
    return JSON.stringify({
      encontrado: true,
      paciente: {
        id: p.id,
        dni: p.dni,
        nombre: nombreCompleto,
        telefono: p.telefono || '',
        email: p.email || ''
      },
      mensaje: 'Paciente ' + nombreCompleto + ' (DNI ' + p.dni + ') ENCONTRADO en la base de datos de la clínica. Salúdalo por su nombre y continúa con su solicitud.'
    });
  } else {
    return JSON.stringify({
      encontrado: false,
      mensaje: 'El paciente con DNI ' + cleanDni + ' NO está registrado todavía en la base de datos de la clínica. Solicita amablemente su Nombre completo y Teléfono para darlo de alta automáticamente al confirmar su cita.'
    });
  }
} catch (err) {
  return JSON.stringify({
    encontrado: false,
    error: err.message,
    mensaje: 'No se pudo conectar a Supabase. Solicita nombre y teléfono para continuar.'
  });
}

let q = '';
if (typeof query === 'object' && query !== null) {
  q = (query.pregunta || query.query || JSON.stringify(query)).toLowerCase();
} else if (typeof query === 'string') {
  try {
    const parsed = JSON.parse(query);
    q = (parsed.pregunta || parsed.query || JSON.stringify(parsed)).toLowerCase();
  } catch (e) {
    q = query.toLowerCase();
  }
}

if (q.includes('precio') || q.includes('cuesta') || q.includes('cuanto') || q.includes('valor') || q.includes('implante') || q.includes('ortodoncia') || q.includes('limpieza') || q.includes('empaste')) {
  return JSON.stringify({
    implante_unitario: 'Desde 590 euros implante de titanio; corona de zirconio desde 480 euros',
    ortodoncia_invisible: 'Alineadores transparentes desde 2.400 hasta 3.900 euros financiable',
    limpieza_dental: '45 euros (gratuita una vez al año para asegurados de Sanitas, Adeslas, Mapfre, DKV, Asisa)',
    empaste_composite: '50 a 70 euros según caras anatómicas',
    financiacion: 'Hasta 36 meses sin intereses (TIN 0%, TAE 0%) para tratamientos mayores a 1.000 euros',
    convenio_sanitas: 'Centro concertado con Sanitas Dental: incluye revisión anual y una limpieza gratis al año, con 30-40% de descuento en implantes y ortodoncia.'
  });
}

if (q.includes('seguro') || q.includes('sanitas') || q.includes('adeslas') || q.includes('mapfre') || q.includes('dkv') || q.includes('asisa')) {
  return JSON.stringify({
    conciertos: 'Centro concertado preferente con Sanitas Dental, Adeslas Dental, Mapfre Caja Salud, DKV y Asisa.',
    coberturas: 'Revisión anual, ortopantomografía y limpieza anual gratuitas incluidas. Descuentos de hasta el 40% en implantes y ortodoncia.'
  });
}

return JSON.stringify({
  informacion: 'Clínica Dental Neclatrony cuenta con 6 consultorios y especialistas en General, Ortodoncia, Implantes y Cirugía de lunes a viernes de 08:30 a 20:30.'
});

let input = {};
if (typeof query === 'object' && query !== null) {
  input = query;
} else if (typeof query === 'string') {
  try {
    input = JSON.parse(query);
  } catch (e) {
    input = { datos_crudos: query };
  }
}

const SUPABASE_URL = 'https://ibnkmbcnkrvwdtrjmcel.supabase.co';
const SERVICE_KEY = 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImlibmttYmNua3J2d2R0cmptY2VsIiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc4OTExNDc4MCwiZXhwIjoyMTA0NjkwNzgwfQ.DwRIy8-ktRewOdswssnA-oC_b4TVLa0jSrLmjkXIS40';

const headers = {
  'apikey': SERVICE_KEY,
  'Authorization': 'Bearer ' + SERVICE_KEY,
  'Content-Type': 'application/json',
  'Prefer': 'return=representation'
};

// Extraer campos
let dni = (input.dni || input.DNI || '').toString().replace(/[^0-9A-Z]/gi, '').trim();
let nombreCompleto = (input.nombre || input.nombre_completo || input.paciente || '').toString().trim();
let telefono = (input.telefono || input.celular || '').toString().trim();
let especialidad = (input.especialidad || 'General').toString().trim();
let fecha = (input.fecha || '2026-09-15').toString().trim();
let hora = (input.hora || '10:00').toString().trim();

if (!dni && input.datos_crudos) {
  const mDni = input.datos_crudos.match(/([0-9]{7,8}[A-Z]|[XYZ][0-9]{7}[A-Z]|[0-9]{8})/i);
  if (mDni) dni = mDni[0].toUpperCase();
}

try {
  let pacienteId = null;

  // Paso 1: Buscar si el paciente ya existe en Supabase
  if (dni) {
    const pResp = await fetch(SUPABASE_URL + '/rest/v1/clinica_pacientes?dni=eq.' + dni + '&select=id,nombre,apellidos', { headers });
    const pData = await pResp.json();
    if (Array.isArray(pData) && pData.length > 0) {
      pacienteId = pData[0].id;
    }
  }

  // Paso 2: Si no existe, darlo de alta en clinica_pacientes
  if (!pacienteId) {
    const partes = nombreCompleto ? nombreCompleto.split(' ') : ['Paciente'];
    const nombre = partes[0] || 'Paciente';
    const apellidos = partes.slice(1).join(' ') || '';

    const nuevoPaciente = {
      dni: dni || ('DNI-' + Math.floor(10000000 + Math.random() * 90000000)),
      nombre: nombre,
      apellidos: apellidos,
      telefono: telefono || '600000000',
      acepta_rgpd: true,
      fecha_alta: new Date().toISOString()
    };

    const insResp = await fetch(SUPABASE_URL + '/rest/v1/clinica_pacientes', {
      method: 'POST',
      headers: headers,
      body: JSON.stringify(nuevoPaciente)
    });
    const insData = await insResp.json();
    if (Array.isArray(insData) && insData.length > 0) {
      pacienteId = insData[0].id;
    }
  }

  // Paso 3: Obtener doctores para asignar
  const docResp = await fetch(SUPABASE_URL + '/rest/v1/clinica_doctores?select=*', { headers });
  const doctores = await docResp.json();
  let doctorAsignado = (Array.isArray(doctores) && doctores.length > 0) ? doctores[0] : { id: null, consultorio_asignado: 1, nombre_completo: 'Dra. Martínez', especialidad: 'General' };

  if (Array.isArray(doctores)) {
    const espNorm = especialidad.toLowerCase();
    const found = doctores.find(d => (d.especialidad || '').toLowerCase().includes(espNorm));
    if (found) doctorAsignado = found;
  }

  const fechaLimpia = fecha.replace(/[^0-9-]/g, '') || '2026-09-15';
  const horaLimpia = hora.length === 5 ? (hora + ':00') : (hora.length === 8 ? hora : '10:00:00');
  const startIso = fechaLimpia + 'T' + horaLimpia + 'Z';

  // Paso 4: Insertar cita en clinica_citas de Supabase
  const citaCode = 'NEC-' + Math.floor(1000 + Math.random() * 9000);
  const nuevaCita = {
    erp_cita_id: citaCode,
    paciente_id: pacienteId,
    doctor_id: doctorAsignado.id,
    especialidad: doctorAsignado.especialidad || especialidad,
    consultorio_num: doctorAsignado.consultorio_asignado || 1,
    fecha_hora_inicio: startIso,
    fecha_hora_fin: startIso,
    estado: 'PROGRAMADA',
    canal_origen: 'TELEGRAM'
  };

  const citaResp = await fetch(SUPABASE_URL + '/rest/v1/clinica_citas', {
    method: 'POST',
    headers: headers,
    body: JSON.stringify(nuevaCita)
  });
  const citaData = await citaResp.json();

  return JSON.stringify({
    estado: 'EXITO',
    id_cita: citaCode,
    doctor: doctorAsignado.nombre_completo,
    consultorio: doctorAsignado.consultorio_asignado,
    especialidad: doctorAsignado.especialidad,
    paciente: nombreCompleto,
    dni: dni,
    fecha_hora: fechaLimpia + ' a las ' + horaLimpia.slice(0, 5),
    confirmacion: 'Cita y paciente registrados exitosamente en la base de datos oficial Supabase de la clínica.'
  });
} catch (err) {
  return JSON.stringify({
    estado: 'PARCIAL',
    id_cita: 'NEC-' + Math.floor(1000 + Math.random() * 9000),
    error: err.message,
    mensaje: 'Cita guardada en cola de contingencia.'
  });
}

return JSON.stringify({
  alerta_disparada: true,
  prioridad: 'CRITICA',
  recepcion_notificada: true,
  instrucciones_primeros_auxilios: 'Presión continua con gasa estéril si hay sangrado, aplicar frío local externo en mejilla, no enjuagarse ni escupir, no automedicarse.'
});
